  ]$j$::jsonb) as v(x text, pl text, en text, p text[], s text[], q text[], m text, k text, l text, d text, c text, t text)
)
insert into public.exercises (name_pl, name_en, primary_muscles, secondary_muscles, muscle_groups, equipment, movement_pattern, mechanic, force, level, description, cues, cues_lang, search_terms, source, external_id)
select v.pl, v.en, v.p, v.s, v.p || v.s, v.q, v.m, v.k,
  case when v.x like 'iso-%' then 'static' when v.m in ('pull_h', 'pull_v') then 'pull' when v.m in ('push_h', 'push_v', 'squat', 'lunge') then 'push' when v.m = 'hinge' then 'pull' else null end,
  v.l::exercise_level, v.d, v.c, 'pl', v.t, 'library', 'bw-' || v.x
from v
where not exists (select 1 from public.exercises e where lower(e.name_pl) = lower(v.pl) or e.external_id = 'bw-' || v.x);

-- ===================== Nowe kategorie sprzętu w istniejących ćwiczeniach =====================
update public.exercises set equipment = array['pull-up bar']
where name_en in ('Negative Pull-Up', 'Scapular Pull-Up', 'Archer Pull-Up', 'One Arm Chin-Up', 'Pullups', 'Chin-Up', 'V-Bar Pullup', 'Jumping Pull-Up', 'Wide-Grip Rear Pull-Up', 'Hanging Knee Raise', 'Hanging Leg Raise', 'Hanging Pike', 'Pull-Up Isometric Hold')
  and source <> 'own';
update public.exercises set equipment = array['dip bars']
where name_en in ('Parallel Bar Dip', 'Dips - Chest Version', 'Dips - Triceps Version', 'Knee/Hip Raise On Parallel Bars') and source <> 'own';
update public.exercises set equipment = array['sled']
where name_en in ('Bear Crawl Sled Drags', 'Forward Drag with Press', 'Backward Drag', 'Sled Drag - Harness', 'Sled Overhead Backward Walk', 'Sled Reverse Flye', 'Sled Push', 'Sled Row', 'Sled Overhead Triceps Extension')
  and source <> 'own';
update public.exercises set equipment = array['roman chair'] where name_en = 'Hyperextensions (Back Extensions)' and source <> 'own';
update public.exercises set equipment = array['trap bar'] where name_en = 'Trap Bar Deadlift' and source <> 'own';
update public.exercises set equipment = array['box']
where name_en in ('Box Skip', 'Lateral Box Jump', 'Front Box Jump', 'Box Jump (Multiple Response)', 'Depth Jump Leap', 'Linear Depth Jump') and equipment = array['other'];
update public.exercises set equipment = array['barbell', 'landmine']
where (name_en in ('Landmine Squat to Press', 'Landmine Rotation', 'Landmine 180''s', 'Landmine Linear Jammer') or name_pl = 'Wyciskanie landmine z klęku do wstawania')
  and not ('landmine' = any(equipment));

-- ===================== Bodywork: nowy sprzęt i maszyny do prostowania / uginania nóg =====================
update public.gyms g set
  equipment = (select array(select distinct x from unnest(coalesce(g.equipment, '{}') || array['trap bar', 'landmine', 'flywheel', 'conical pulley', 'sled', 'pull-up bar', 'dip bars', 'roman chair', 'mini band']) x)),
  machines = case when g.machines is null then null else (
    select array(select distinct x from unnest(g.machines || array(
      select id from public.exercises
      where name_en in ('Leg Extensions', 'Single-Leg Leg Extension', 'Seated Leg Curl', 'Lying Leg Curls', 'Leg Extension Isometric Hold', 'Leg Curl Isometric Hold')
    )) x)) end
where g.name = 'Bodywork';
